//! Setting metadata for the editor: labels, tooltips, units, ranges, Simple/Advanced mode and
//! the Orca-style page layout. Both tables are generated by `cargo xtask gen-option-text`; the
//! help text shown for each setting is Mica's own, hand-written in `help_text.tsv`.

/// docs/setting-names.md, generated and checked by this module's test.
#[cfg(test)]
pub mod names;
pub mod unimplemented;

use mica_core::config::{OptType, option_defs};
use std::collections::BTreeMap;
use std::sync::OnceLock;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Tab {
    Print,
    Filament,
    Printer,
}

impl Tab {
    fn id(self) -> &'static str {
        match self {
            Tab::Print => "print",
            Tab::Filament => "filament",
            Tab::Printer => "printer",
        }
    }
}

#[derive(Clone, Debug)]
pub struct OptionText {
    pub label: String,
    pub full_label: String,
    pub unit: String,
    pub min: Option<f64>,
    pub max: Option<f64>,
    /// Hidden unless the Advanced toggle is on.
    pub advanced: bool,
    /// Mica's help text (`help_text.tsv`), shown as the tooltip and searched.
    pub tooltip: String,
    /// The upstream tooltip the generator copied (`option_text.tsv`): reference data for
    /// writing the help text, never shown.
    #[cfg_attr(not(test), allow(dead_code))]
    pub upstream_tooltip: String,
    /// Enum choices (value, label), PrusaSlicer vocabulary.
    pub enums: Vec<(String, String)>,
    /// Where the text comes from: `orca:<key>`, `orca-label:<key>`, `prusa` or `mica`.
    #[cfg_attr(not(test), allow(dead_code))]
    pub source: String,
    /// PrusaSlicer's and OrcaSlicer's own labels (empty where that slicer lacks the option),
    /// for docs/setting-names.md.
    #[cfg_attr(not(test), allow(dead_code))]
    pub prusa_label: String,
    #[cfg_attr(not(test), allow(dead_code))]
    pub orca_label: String,
}

#[derive(Clone, Debug)]
pub struct Line {
    pub label: String,
    pub keys: Vec<&'static str>,
}

#[derive(Clone, Debug)]
pub struct Group {
    pub name: String,
    pub lines: Vec<Line>,
}

#[derive(Clone, Debug)]
pub struct Page {
    pub name: String,
    pub groups: Vec<Group>,
}

fn unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => out.push('\n'),
                Some('t') => out.push('\t'),
                Some(other) => out.push(other),
                None => {}
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Label, tooltip and range of every editable option, by canonical key.
pub fn text() -> &'static BTreeMap<&'static str, OptionText> {
    static TEXT: OnceLock<BTreeMap<&'static str, OptionText>> = OnceLock::new();
    TEXT.get_or_init(|| {
        // Generated rows, then the hand-written ones (which replace a generated row).
        let mut all: BTreeMap<&'static str, OptionText> = include_str!("option_text.tsv")
            .lines()
            .chain(include_str!("mica_text.tsv").lines())
            .filter(|l| !l.starts_with('#') && !l.is_empty())
            .filter_map(|line| {
                let f: Vec<&str> = line.split('\t').collect();
                if f.len() < 10 {
                    return None;
                }
                let key: &'static str = option_defs().get_key_value(f[0])?.0;
                Some((
                    key,
                    OptionText {
                        label: unescape(f[1]),
                        full_label: unescape(f[2]),
                        unit: unescape(f[4]),
                        min: f[5].parse().ok(),
                        max: f[6].parse().ok(),
                        advanced: f[7] == "advanced",
                        tooltip: String::new(),
                        upstream_tooltip: unescape(f[8]),
                        enums: f[9]
                            .split('|')
                            .filter(|e| !e.is_empty())
                            .filter_map(|e| {
                                e.split_once('=')
                                    .map(|(v, l)| (v.to_string(), l.to_string()))
                            })
                            .collect(),
                        source: f.get(10).map_or_else(String::new, |s| s.to_string()),
                        prusa_label: f.get(11).map_or_else(String::new, |s| unescape(s)),
                        orca_label: f.get(12).map_or_else(String::new, |s| unescape(s)),
                    },
                ))
            })
            .fold(BTreeMap::new(), |mut all, (key, mut t)| {
                // A hand-written row keeps the upstream labels of the generated one.
                if let Some(old) = all.get(key) {
                    let old: &OptionText = old;
                    if t.prusa_label.is_empty() {
                        t.prusa_label = old.prusa_label.clone();
                    }
                    if t.orca_label.is_empty() {
                        t.orca_label = old.orca_label.clone();
                    }
                    if t.upstream_tooltip.is_empty() {
                        t.upstream_tooltip = old.upstream_tooltip.clone();
                    }
                }
                all.insert(key, t);
                all
            });
        // Mica's own help text, label and choice wording over the upstream data.
        for (key, t) in all.iter_mut() {
            let Some(h) = help_table().get(key) else {
                continue;
            };
            t.tooltip = h.text.clone();
            if let Some(label) = &h.label {
                if t.full_label == t.label {
                    t.full_label = label.clone();
                }
                t.label = label.clone();
            }
            for (value, label) in &mut t.enums {
                if let Some((_, new)) = h.choices.iter().find(|(v, _)| v == value) {
                    *label = new.clone();
                }
            }
        }
        all
    })
}

/// One row of `help_text.tsv`.
struct Help {
    text: String,
    label: Option<String>,
    choices: Vec<(String, String)>,
}

/// Mica's help text by key: every option, the synthetic Essentials keys and the engine
/// extras the editor shows (`brim_ears`).
fn help_table() -> &'static BTreeMap<&'static str, Help> {
    static HELP: OnceLock<BTreeMap<&'static str, Help>> = OnceLock::new();
    HELP.get_or_init(|| {
        include_str!("help_text.tsv")
            .lines()
            .filter(|l| !l.starts_with('#') && !l.is_empty())
            .filter_map(|line| {
                let f: Vec<&'static str> = line.split('\t').collect();
                let text = unescape(f.get(1)?);
                let label = f.get(2).filter(|l| !l.is_empty()).map(|l| unescape(l));
                let choices = f
                    .get(3)
                    .into_iter()
                    .flat_map(|c| c.split('|'))
                    .filter_map(|e| e.split_once('='))
                    .map(|(v, l)| (v.to_string(), l.to_string()))
                    .collect();
                Some((
                    f[0],
                    Help {
                        text,
                        label,
                        choices,
                    },
                ))
            })
            .collect()
    })
}

/// Mica's help text for a setting (empty if it has none).
pub fn help(key: &str) -> &'static str {
    help_table().get(key).map_or("", |h| h.text.as_str())
}

/// The option's label as it reads on its own ("Nozzle temperature, other layers"), out of its
/// page's context; the short label when there is no longer one.
pub fn full_label(key: &str) -> String {
    match text().get(key) {
        Some(t) if !t.full_label.is_empty() => t.full_label.clone(),
        _ => label(key),
    }
}

/// Label of an option (the key itself if unknown).
pub fn label(key: &str) -> String {
    text()
        .get(key)
        .map_or_else(|| key.to_string(), |t| t.label.clone())
}

/// Whether `key` is on a Printer settings page (a fix that sets it changes the printer).
pub fn on_printer_tab(key: &str) -> bool {
    static KEYS: OnceLock<std::collections::BTreeSet<&'static str>> = OnceLock::new();
    KEYS.get_or_init(|| {
        pages(Tab::Printer)
            .iter()
            .flat_map(|p| p.groups.iter())
            .flat_map(|g| g.lines.iter())
            .flat_map(|l| l.keys.iter().copied())
            .collect()
    })
    .contains(key)
}

/// Whether printer option `key` has one value per extruder: it is on the printer's Extruder
/// page, which the editor shows once per extruder.
pub fn is_per_extruder(key: &str) -> bool {
    static KEYS: OnceLock<std::collections::BTreeSet<&'static str>> = OnceLock::new();
    KEYS.get_or_init(|| {
        pages(Tab::Printer)
            .iter()
            .filter(|p| p.name == "Extruder")
            .flat_map(|p| p.groups.iter())
            .flat_map(|g| g.lines.iter())
            .flat_map(|l| l.keys.iter().copied())
            .collect()
    })
    .contains(key)
}

/// The pages of a tab, in display order.
pub fn pages(tab: Tab) -> &'static [Page] {
    static PAGES: OnceLock<BTreeMap<&'static str, Vec<Page>>> = OnceLock::new();
    PAGES
        .get_or_init(|| {
            let mut out: BTreeMap<&'static str, Vec<Page>> = BTreeMap::new();
            for line in include_str!("pages.tsv")
                .lines()
                .filter(|l| !l.starts_with('#') && !l.is_empty())
            {
                let f: Vec<&str> = line.split('\t').collect();
                if f.len() < 5 {
                    continue;
                }
                let Some((key, _)) = option_defs().get_key_value(f[4]) else {
                    continue;
                };
                // Purging into a whole object is an object setting only: OrcaSlicer hides it in
                // the process settings (`toggle_line("flush_into_objects", !is_global_config)`)
                // and PrusaSlicer's print settings have no row for it.
                if *key == "wipe_into_objects" {
                    continue;
                }
                let tab = match f[0] {
                    "print" => "print",
                    "filament" => "filament",
                    _ => "printer",
                };
                let (page, group, label) = (unescape(f[1]), unescape(f[2]), unescape(f[3]));
                let pages = out.entry(tab).or_default();
                if pages.last().is_none_or(|p| p.name != page) {
                    // A page can be revisited (Orca's "More settings" fallbacks); merge by name.
                    if let Some(i) = pages.iter().position(|p| p.name == page) {
                        let moved = pages.remove(i);
                        pages.push(moved);
                    } else {
                        pages.push(Page {
                            name: page.clone(),
                            groups: vec![],
                        });
                    }
                }
                let groups = &mut pages.last_mut().unwrap().groups;
                if groups.last().is_none_or(|g| g.name != group) {
                    groups.push(Group {
                        name: group.clone(),
                        lines: vec![],
                    });
                }
                let lines = &mut groups.last_mut().unwrap().lines;
                if !label.is_empty() && lines.last().is_some_and(|l| l.label == label) {
                    lines.last_mut().unwrap().keys.push(key);
                } else {
                    lines.push(Line {
                        label,
                        keys: vec![key],
                    });
                }
            }
            place_mica_rows(&mut out);
            // Orca's order for the pages that take fallbacks; keep extruder pages last.
            for pages in out.values_mut() {
                let order = |p: &Page| match p.name.as_str() {
                    "Quality" | "Basic information" | "Filament" => 0,
                    "Strength" | "Machine G-code" | "Cooling" => 1,
                    "Speed" | "Motion ability" | "Advanced" => 2,
                    "Support" | "Extruder" | "Texture" => 3,
                    "Multimaterial" => 4,
                    "Others" => 5,
                    "Notes" => 6,
                    _ => 7,
                };
                pages.sort_by_key(order);
            }
            out
        })
        .get(tab.id())
        .map_or(&[], Vec::as_slice)
}

/// Hand-placed rows (`mica_pages.tsv`): after a given key in its group, as a new group after
/// a named one (`group:Name`), or as a new group opening the page. A page no upstream row names (Mica's own "Texture") is created, and its
/// groups follow in file order.
fn place_mica_rows(out: &mut BTreeMap<&'static str, Vec<Page>>) {
    let mut own_pages: Vec<String> = Vec::new();
    for line in include_str!("mica_pages.tsv")
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
    {
        let f: Vec<&str> = line.split('\t').collect();
        let Some((key, _)) = option_defs().get_key_value(f[4]) else {
            continue;
        };
        let tab = match f[0] {
            "print" => "print",
            "filament" => "filament",
            _ => "printer",
        };
        let (page, group, label) = (unescape(f[1]), unescape(f[2]), unescape(f[3]));
        let after = f.get(5).copied().unwrap_or("");
        let pages = out.entry(tab).or_default();
        if MICA_PAGES.contains(&page.as_str()) && !pages.iter().any(|p| p.name == page) {
            own_pages.push(page.clone());
            pages.push(Page {
                name: page.clone(),
                groups: vec![],
            });
        }
        let own = own_pages.contains(&page);
        let Some(page) = pages.iter_mut().find(|p| p.name == page) else {
            continue;
        };
        let row = Line {
            label,
            keys: vec![key],
        };
        // `group:Name`: a new group right after the group `Name`.
        let after_group = after
            .strip_prefix("group:")
            .and_then(|name| page.groups.iter().position(|g| g.name == name));
        let anchor = page.groups.iter_mut().find_map(|g| {
            let i = g.lines.iter().position(|l| l.keys.contains(&after))?;
            Some((g, i))
        });
        match anchor {
            Some((g, i)) if !after.is_empty() => g.lines.insert(i + 1, row),
            _ if after_group.is_some() => page.groups.insert(
                after_group.unwrap_or(0) + 1,
                Group {
                    name: group,
                    lines: vec![row],
                },
            ),
            _ if own => page.groups.push(Group {
                name: group,
                lines: vec![row],
            }),
            _ => page.groups.insert(
                0,
                Group {
                    name: group,
                    lines: vec![row],
                },
            ),
        }
    }
}

/// Pages of Mica's own settings (`mica_pages.tsv`), shown as their own sidebar topics.
pub const MICA_PAGES: &[&str] = &["Texture"];

/// One line under Printer settings → Basic information for the "Slicing rules" switch.
pub const RULES_DESCRIPTION: &str = "Slicing rules: which slicer's behavior Mica follows for walls, \
     seams, travel, cooling and tool changes. Firmware commands are set by G-code flavor.";

/// The printer card's badge for the slicing rules.
pub fn rules_badge(rules: mica_core::rules::Rules) -> &'static str {
    match rules {
        mica_core::rules::Rules::PrusaSlicer => "PrusaSlicer rules",
        mica_core::rules::Rules::OrcaSlicer => "Orca rules",
    }
}

/// Whether `key` is the PrusaSlicer counterpart of a merged setting (wall order, scarf seams;
/// `mica_core::merged`). The Orca key is shown under both rules instead, and its edits write
/// the counterpart too.
pub fn merged_away(key: &str) -> bool {
    mica_core::merged::is_counterpart(key)
}

/// Whether an option matters with the configuration's other values: the settings of one sparse
/// infill pattern only show while that pattern is selected (as in OrcaSlicer's settings tab).
pub fn relevant(key: &str, c: &mica_core::config::Config) -> bool {
    let pattern = c.string("fill_pattern").unwrap_or_default();
    match key {
        "infill_shift_step" => matches!(pattern, "crosszag" | "lockedzag"),
        "symmetric_infill_y_axis" => matches!(pattern, "zigzag" | "crosszag" | "lockedzag"),
        "skin_infill_density"
        | "skeleton_infill_density"
        | "skin_infill_depth"
        | "infill_lock_depth"
        | "skin_infill_line_width"
        | "skeleton_infill_line_width" => pattern == "lockedzag",
        _ => true,
    }
}

/// Whether an option applies under the printer's slicing rules. PrusaSlicer-only switches that
/// OrcaSlicer's rules ignore are hidden under Orca rules, and Orca-only options PrusaSlicer's
/// rules ignore under PrusaSlicer rules (see docs/slicing-rules.md). Options that work the
/// same under both stay.
pub fn applies(key: &str, rules: mica_core::rules::Rules) -> bool {
    if merged_away(key) {
        return false;
    }
    const PRUSA_ONLY: &[&str] = &[
        // Orca cools uniformly.
        "cooling_slowdown_logic",
        "cooling_perimeter_transition_distance",
        // Orca prints walls first.
        "infill_first",
        // Orca's Z-hop type decides the travel lift.
        "travel_ramping_lift",
        "travel_lift_before_obstacle",
        "travel_max_lift",
        "filament_travel_ramping_lift",
        "filament_travel_lift_before_obstacle",
        "filament_travel_max_lift",
        // Orca emits no automatic temperature commands around the start G-code and picks the
        // bed temperature by its own formula.
        "autoemit_temperature_commands",
        "bed_temperature_extruder",
        "travel_short_distance_acceleration",
        // Orca has no tool-change ordering choice (it orders tools to minimize flushing).
        "toolchange_ordering",
    ];
    const ORCA_ONLY: &[&str] = &[
        // Orca's scarf extras PrusaSlicer's scarf code has no equivalent for.
        "scarf_angle_threshold",
        "scarf_overhang_threshold",
        "scarf_joint_speed",
        "scarf_joint_flow_ratio",
        "support_remove_small_overhang",
        "support_interface_not_for_body",
        "bridge_line_width",
        "z_hop_types",
    ];
    if rules.is_orca() {
        !PRUSA_ONLY.contains(&key)
    } else {
        !ORCA_ONLY.contains(&key)
    }
}

/// Whether an option matches a search query (key, label or tooltip, case-insensitive).
pub fn matches(key: &str, query: &str) -> bool {
    let q = query.trim().to_lowercase();
    if q.is_empty() {
        return true;
    }
    let hit = |key: &str| {
        key.to_lowercase().contains(&q)
            || text().get(key).is_some_and(|t| {
                t.label.to_lowercase().contains(&q)
                    || t.full_label.to_lowercase().contains(&q)
                    || t.tooltip.to_lowercase().contains(&q)
            })
    };
    // A merged setting is also found by its PrusaSlicer name.
    hit(key) || mica_core::merged::by_orca(key).is_some_and(|p| hit(p.prusa))
}

/// Whether an option picks a tool (one-based, 0 for "default" where allowed): its value never
/// exceeds the printer's tool count.
pub fn is_tool_selector(key: &str) -> bool {
    matches!(
        key,
        "extruder"
            | "perimeter_extruder"
            | "infill_extruder"
            | "solid_infill_extruder"
            | "support_material_extruder"
            | "support_material_interface_extruder"
            | "wipe_tower_extruder"
            | "bed_temperature_extruder"
    )
}

/// Whether an option is a long text (custom G-code, notes) best edited in a multi-line box.
pub fn is_long_text(key: &str) -> bool {
    option_defs()
        .get(key)
        .is_some_and(|d| matches!(d.ty, OptType::String | OptType::Strings))
        && (key.contains("gcode")
            || key.contains("notes")
            || key.contains("custom_parameters")
            || key == "small_area_infill_flow_compensation_model")
}

/// Synthetic key for the Essentials "Supports" mode (off / enforcers only / everywhere / build
/// plate only), which stands for `support_material`, `support_material_auto` and
/// `support_material_buildplate_only` together.
pub const SUPPORT_MODE: &str = "mica:support_mode";
/// Synthetic key for the combined `5 / 3 layers` field (`top_solid_layers` and
/// `bottom_solid_layers`).
pub const TOP_BOTTOM: &str = "mica:top_bottom";

/// The real keys a synthetic key edits.
pub fn synthetic_keys(key: &str) -> &'static [&'static str] {
    match key {
        SUPPORT_MODE => &[
            "support_material",
            "support_material_auto",
            "support_material_buildplate_only",
        ],
        TOP_BOTTOM => &["top_solid_layers", "bottom_solid_layers"],
        _ => &[],
    }
}

/// Settings that only matter once another one is switched on: `(parent, dependents)`. The
/// sidebar shows the dependents right under their parent, indented, while
/// [`dependents_active`] holds, and hides them again when the parent is switched off. They
/// still appear in their home sections, and search finds them in both places.
pub const DEPENDENTS: &[(&str, &[&str])] = &[
    (
        "small_area_infill_flow_compensation",
        &["small_area_infill_flow_compensation_model"],
    ),
    (
        "ironing",
        &[
            "ironing_type",
            "ironing_flowrate",
            "ironing_spacing",
            "ironing_speed",
        ],
    ),
    (
        // The Essentials mode already encodes "build plate only", so it is left out here.
        SUPPORT_MODE,
        &[
            "support_material_style",
            "support_material_threshold",
            "support_material_contact_distance",
        ],
    ),
    (
        "support_material",
        &[
            "support_material_style",
            "support_material_threshold",
            "support_material_buildplate_only",
            "support_material_contact_distance",
        ],
    ),
    (
        "overhang_reverse",
        &[
            "overhang_reverse_internal_only",
            "overhang_reverse_threshold",
        ],
    ),
    (
        "seam_slope_type",
        &[
            "seam_slope_conditional",
            "scarf_angle_threshold",
            "scarf_overhang_threshold",
            "scarf_joint_speed",
            "scarf_joint_flow_ratio",
            "seam_slope_start_height",
            "seam_slope_entire_loop",
            "seam_slope_min_length",
            "seam_slope_steps",
            "seam_slope_inner_walls",
        ],
    ),
    (
        "brim_type",
        &[
            "brim_width",
            "brim_separation",
            // Orca's automatic ears; shown only for that type (`brim_ears::option_shown`).
            "brim_ears_max_angle",
            "brim_ears_detection_length",
        ],
    ),
    ("skirts", &["skirt_distance", "skirt_height"]),
    (
        "fuzzy_skin",
        &["fuzzy_skin_thickness", "fuzzy_skin_point_dist"],
    ),
];

/// The dependents of `key` (empty for most settings).
pub fn dependents(key: &str) -> &'static [&'static str] {
    DEPENDENTS
        .iter()
        .find(|(k, _)| *k == key)
        .map_or(&[], |(_, deps)| deps)
}

/// Whether `key`'s dependents matter with the configuration `c`: the toggle is on, the mode is
/// not "off" / "none" / "nowhere", the count is above zero.
pub fn dependents_active(key: &str, c: &mica_core::config::Config) -> bool {
    match key {
        "ironing" => c.bool("ironing") == Some(true),
        "overhang_reverse" => c.bool("overhang_reverse") == Some(true),
        "seam_slope_type" => {
            mica_core::merged::orca_raw(c, "seam_slope_type").is_some_and(|s| s != "none")
        }
        SUPPORT_MODE | "support_material" => c.bool("support_material") == Some(true),
        "brim_type" => c.string("brim_type").is_some_and(|v| v != "no_brim"),
        "skirts" => c.int("skirts").is_some_and(|n| n > 0),
        "fuzzy_skin" => c.string("fuzzy_skin").is_some_and(|v| v != "none"),
        _ => false,
    }
}

