/// Whether `key` is one of `topic`'s key options (`TOPIC_KEYS`).
pub fn is_topic_key(topic: &str, key: &str) -> bool {
    TOPIC_KEYS
        .iter()
        .any(|(t, keys)| *t == topic && keys.contains(&key))
}

