/// Which level of a selection settings are edited at: an object, a modifier (or another
/// volume with settings), a height range.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Level {
    Object,
    Modifier,
    Range,
}

/// Settings the engine takes from the object for every region of it
/// (`mica_core::regions::region_config`) or applies to the whole object (supports, raft,
/// brim, skirt, the plate's print order): a modifier or a height range cannot change them.
/// A range still takes its own layer height.
fn object_only(key: &str) -> bool {
    matches!(
        key,
        "layer_height"
            | "first_layer_height"
            | "infill_every_layers"
            | "solid_infill_every_layers"
            | "xy_hole_compensation"
            | "xy_contour_compensation"
            | "xy_size_compensation"
            | "elefant_foot_compensation"
            | "complete_objects"
            | "draft_shield"
            | "min_skirt_length"
            | "slice_closing_radius"
            | "slicing_mode"
            | "interface_shells"
            | "dont_support_bridges"
            | "wipe_into_objects"
            | SUPPORT_MODE
    ) || [
        "support_material",
        "support_tree_",
        "raft_",
        "brim_",
        "skirt",
        "wipe_tower",
        "extruder_clearance",
    ]
    .iter()
    .any(|p| key.starts_with(p))
}

/// Whether a print setting can be overridden at `level` (the scope bar's object and part
/// scopes show only these, plus any override already there). An object takes every print
/// setting the profile has, as its "+ Add override" menu and search always did, except the
/// tool selectors (an object's tools are its own field); a modifier takes the per-region
/// ones; a height range those and its layer height. Settings Mica does not implement
/// (`unimplemented`) are never offered.
pub fn scope_allows(level: Level, key: &str) -> bool {
    if unimplemented::hidden_everywhere(key) {
        return false;
    }
    let real = synthetic_keys(key);
    let print = |k: &str| {
        option_defs()
            .get(k)
            .is_some_and(|d| d.scope == mica_core::config::Scope::Print)
            && !is_tool_selector(k)
    };
    let object = if real.is_empty() {
        print(key)
    } else {
        real.iter().all(|k| print(k))
    };
    match level {
        Level::Object => object,
        Level::Modifier => object && !object_only(key),
        Level::Range => object && (key == "layer_height" || !object_only(key)),
    }
}

