    /// The U1's Z-hop type (Orca rules) is on the printer's Extruder › Travel lift group, first,
    /// shown on Klipper printers and in Simple mode, and hidden under PrusaSlicer rules (the
    /// ramping lift decides there). Orca's filament override `filament_z_hop_types` is not a
    /// Mica option: the profile value is kept and the engine reads it (`orca_motion`).
    #[test]
    fn z_hop_type_is_in_the_printer_travel_lift_group_under_orca_rules() {
        let extruder = pages(Tab::Printer)
            .iter()
            .find(|p| p.name == "Extruder")
            .unwrap();
        let lift = extruder
            .groups
            .iter()
            .find(|g| g.name == "Travel lift")
            .unwrap();
        assert_eq!(lift.lines[0].keys, ["z_hop_types"]);
        assert!(applies("z_hop_types", mica_core::rules::Rules::OrcaSlicer));
        assert!(!applies(
            "z_hop_types",
            mica_core::rules::Rules::PrusaSlicer
        ));
        assert!(unimplemented::setting("z_hop_types").is_none());
        assert!(!text()["z_hop_types"].advanced);
    }

    /// Every key the editor can show: page rows, Essentials, topic key options, the cooling and
    /// filament rows, dependents and the object override menu.
    fn shown_keys() -> std::collections::BTreeSet<&'static str> {
        let mut keys = std::collections::BTreeSet::new();
        for tab in [Tab::Print, Tab::Filament, Tab::Printer] {
            for p in pages(tab) {
                for g in &p.groups {
                    for l in &g.lines {
                        keys.extend(l.keys.iter().copied());
                    }
                }
            }
        }
        keys.extend(ESSENTIALS_CURATED.iter().map(|(k, _)| *k));
        for (_, ks) in ESSENTIALS_MORE
            .iter()
            .chain(TOPIC_KEYS)
            .chain(DEPENDENTS)
            .chain(OBJECT_OVERRIDES)
        {
            keys.extend(ks.iter().copied());
        }
        keys.extend(DEPENDENTS.iter().map(|(k, _)| *k));
        keys.extend(COOLING.iter().chain(ESSENTIAL_FILAMENT).copied());
        keys
    }

    #[test]
    fn every_shown_setting_has_mica_help_text() {
        let missing: Vec<&str> = shown_keys()
            .into_iter()
            .chain(text().keys().copied())
            .filter(|k| help(k).trim().is_empty())
            .collect();
        assert!(
            missing.is_empty(),
            "no help text in help_text.tsv: {missing:?}"
        );
        // No stale rows: every help key is an option, a synthetic key or an engine extra.
        for key in help_table().keys() {
            assert!(
                text().contains_key(key)
                    || option_defs().contains_key(key)
                    || !synthetic_keys(key).is_empty()
                    || crate::brim_ears::ear_option(key).is_some(),
                "{key} in help_text.tsv is not a setting"
            );
        }
        // The tooltip is Mica's text, never the upstream one.
        for (key, t) in text() {
            assert_eq!(t.tooltip, help(key), "{key}");
        }
    }

    #[test]
    fn help_texts_follow_the_style_rules() {
        const BANNED: &[&str] = &["prusaslicer", "prusa slicer", "orca", "bambu", "slic3r"];
        const BRITISH: &[&str] = &[
            "colour",
            "behaviour",
            "neighbour",
            "favour",
            "centre",
            "metre",
            "grey",
            "labelled",
        ];
        for (key, h) in help_table() {
            let all = std::iter::once(h.text.as_str())
                .chain(h.label.as_deref())
                .chain(h.choices.iter().map(|(_, l)| l.as_str()));
            for s in all {
                let lower = s.to_lowercase();
                // The rules may only be named neutrally.
                let neutral = lower
                    .replace("with prusaslicer rules", "")
                    .replace("with orca rules", "");
                for word in BANNED {
                    assert!(!neutral.contains(word), "{key}: names {word}: {s}");
                }
                for word in BRITISH {
                    assert!(!lower.contains(word), "{key}: British spelling {word}: {s}");
                }
                // No hex colors (#RGB, #RRGGBB).
                let hex = s.match_indices('#').any(|(i, _)| {
                    s[i + 1..]
                        .chars()
                        .take_while(char::is_ascii_hexdigit)
                        .count()
                        >= 3
                });
                assert!(!hex, "{key}: hex color: {s}");
            }
            let text = &h.text;
            assert!(
                text.chars().count() <= 400,
                "{key}: {} characters",
                text.len()
            );
            assert!(text.ends_with('.'), "{key}: no final period: {text}");
            assert!(!text.contains("  "), "{key}: double space");
        }
    }

    #[test]
    fn help_choice_labels_name_real_choices() {
        for (key, h) in help_table() {
            if h.choices.is_empty() {
                continue;
            }
            let t = &text()[key];
            for (value, label) in &h.choices {
                assert!(
                    t.enums.iter().any(|(v, l)| v == value && l == label),
                    "{key}: {value} is not a choice"
                );
            }
        }
        // Relabels reach the editor; unlisted choices keep the generated label.
        let t = text();
        assert_eq!(t["fuzzy_skin"].label, "Fuzzy skin");
        assert!(
            t["arc_fitting"]
                .enums
                .contains(&("disabled".into(), "Off".into()))
        );
        assert!(
            t["brim_type"]
                .enums
                .contains(&("no_brim".into(), "No brim".into()))
        );
    }

    /// Settings that behave differently under the two slicing rules say so, in the neutral
    /// form.
    #[test]
    fn rule_dependent_settings_say_how() {
        for key in [
            "retract_layer_change",
            "filament_retract_layer_change",
            "retract_lift",
            "travel_slope",
            "small_perimeter_speed",
            "first_layer_infill_speed",
            "cooling",
            "brim_type",
            "seam_slope_conditional",
            "seam_slope_steps",
            "bridge_fan_speed",
        ] {
            let h = help(key).to_lowercase();
            assert!(
                h.contains("with prusaslicer rules") || h.contains("with orca rules"),
                "{key}: {h}"
            );
        }
    }
